'use strict';
const weekdayNames=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
async function groupList(){const unit=$('groups-unit').value,{groups}=await api('/groups?unit='+unit);$('groups-list').replaceChildren();for(const g of groups){const b=el('button',`${g.label} · ${g.weekdays.map(d=>weekdayNames[d]).join(' e ')} · ${g.start_time}–${g.end_time} · ${g.enrolled} matriculados${g.active?'':' · Inativa'}`,{class:'secondary registration-row'});b.addEventListener('click',action(()=>groupDetail(g.id)));$('groups-list').append(b)}if(!groups.length)$('groups-list').append(el('p','Nenhuma turma cadastrada neste núcleo.'))}
async function groupDetail(id){const g=id?(await api('/groups/'+id)).group:{unit:$('groups-unit').value,label:'',weekdays:[],start_time:'',end_time:'',version:0,active:true,students:(await api('/unit-roster?unit='+$('groups-unit').value)).students.map(s=>({...s,enrolled:false}))},box=$('group-detail');box.hidden=false;box.replaceChildren(el('h3',id?'Editar turma e matrículas':'Cadastrar turma'),el('p','Selecione os alunos deste horário. Cada chamada guarda a lista ao ser aberta; alterações de matrícula valem para as próximas aulas.'));
 const form=el('form');field(form,'Nome da turma','label',g.label).required=true;field(form,'Início da aula','start_time',g.start_time,{type:'time'}).required=true;field(form,'Fim da aula','end_time',g.end_time,{type:'time'}).required=true;const days=el('fieldset');days.append(el('legend','Dias da semana'));weekdayNames.forEach((name,i)=>{const label=el('label',undefined,{class:'check-label'}),input=el('input',undefined,{type:'checkbox',name:'weekdays',value:i});input.checked=g.weekdays.includes(i);label.append(input,document.createTextNode(name));days.append(label)});form.append(days);field(form,'Situação da turma','active',String(g.active),{options:{true:'Ativa',false:'Inativa'}});
 const roster=el('fieldset');roster.append(el('legend','Alunos aprovados do núcleo'));const search=field(roster,'Buscar aluno para matrícula','filter','',{type:'search'}),list=el('div');roster.append(list);for(const s of g.students){const label=el('label',undefined,{class:'check-label enrollment-row'}),input=el('input',undefined,{type:'checkbox',name:'students',value:s.id});input.checked=s.enrolled;label.append(input,document.createTextNode(s.name+' · '+s.id));list.append(label)}search.addEventListener('input',()=>{for(const row of list.children)row.hidden=!row.textContent.toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR'))});form.append(roster,el('button','Salvar turma e matrículas'));form.addEventListener('submit',action(async()=>{const data=new FormData(form),r=await api('/groups'+(id?'/'+id:''),{method:id?'PATCH':'POST',data:{unit:g.unit,label:data.get('label'),start_time:data.get('start_time'),end_time:data.get('end_time'),active:data.get('active')==='true',weekdays:data.getAll('weekdays').map(Number),students:data.getAll('students'),version:g.version}});await groupList();await groupDetail(r.group.id);await loadAttendanceGroups();notice(r.message)}));box.append(form);box.focus({preventScroll:true});box.scrollIntoView({block:'start'});
}
document.addEventListener('portal:loaded',action(async()=>{if(!['admin','secretary'].includes(me.role)){if($('groups-area'))$('groups-area').hidden=true;return}if(!$('groups-area')){const area=el('section',undefined,{id:'groups-area'});$('team-area').before(area);area.append(el('h2','Turmas, horários e matrículas'),el('p','Organize a lista de alunos de cada horário. O professor encontrará essa lista ao abrir a chamada.'));field(area,'Núcleo das turmas','unit','amavale',{options:classUnits,htmlId:'groups-unit'});area.append(el('button','Cadastrar turma',{id:'group-new'}),el('div',undefined,{id:'groups-list'}),el('section',undefined,{id:'group-detail',hidden:'',tabindex:'-1'}));$('group-new').addEventListener('click',action(()=>groupDetail(null)));$('groups-unit').addEventListener('change',action(async()=>{$('group-detail').hidden=true;await groupList()}))}$('groups-area').hidden=false;await groupList()}));
document.addEventListener('portal:logout',()=>{$('groups-area')?.remove()});
